//! 命令树类型化生成源（contract-governance-04-specgen-rebuild）。
//!
//! 把 `novel` CLI 的 `clap` 命令树（`commands::build_cli()`）提升为 `commands.md` 命令语法段
//! 与参数表的类型化源，替代手写语法段 / 参数表的漂移现状。
//!
//! 生成范围（design Decision 3）：只生成「命令语法行」+「参数表」；行为语义段与退出码表
//! 保留手写（`@generated` 标记界定外）。参数表「说明」列取自 `Arg::get_help()`、「必填」列取自
//! `Arg::is_required()`、占位符取自 `Arg::get_value_names()`（回退 arg id，小写）。
//!
//! 边界（CLAUDE.md §3/§8）：spec-gen 是 dev-only xtask，以 lib 形式消费 novel-cli 的命令树
//! （clap `Command`），只读命令 / 参数元数据，不读 SQLite、不读 `.novel/content`。

use clap::{Arg, ArgAction, Command};
use std::collections::HashMap;
use std::path::Path;

use crate::md_render::{GEN_END, GEN_MARKER_PREFIX};

/// 一条叶子命令的可生成元数据。
pub struct LeafCommand {
    /// 完整命令路径（如 `setting set`、`volume goal set`），不含 `novel` 前缀。
    pub name: String,
    /// 参数元数据（按 clap 声明顺序）。
    pub args: Vec<ArgMeta>,
}

/// 一条参数的可生成元数据。
pub struct ArgMeta {
    /// 语法行占位符（如 `<name>`、`--path <dir>`、`--json`）。
    pub syntax_token: String,
    /// 是否必填（`Arg::is_required()`）。
    pub required: bool,
    /// 参数表「说明」列（`Arg::get_help()` 逐字）。
    pub help: String,
}

/// 遍历 `build_cli()` 命令树，收集全部叶子命令（有参数、无子命令）。按声明序稳定输出。
pub fn collect_commands() -> Vec<LeafCommand> {
    let root = novel_cli::commands::build_cli();
    let mut out = Vec::new();
    walk(&root, "", &mut out);
    out
}

fn walk(cmd: &Command, prefix: &str, out: &mut Vec<LeafCommand>) {
    for sub in cmd.get_subcommands() {
        let name = if prefix.is_empty() {
            sub.get_name().to_string()
        } else {
            format!("{prefix} {}", sub.get_name())
        };
        if sub.get_subcommands().next().is_some() {
            walk(sub, &name, out);
        } else {
            out.push(build_leaf(&name, sub));
        }
    }
}

fn build_leaf(name: &str, cmd: &Command) -> LeafCommand {
    let mut args = Vec::new();
    for arg in cmd.get_arguments() {
        args.push(ArgMeta {
            syntax_token: render_syntax_token(arg),
            required: arg.is_required_set(),
            help: arg.get_help().map(|h| h.to_string()).unwrap_or_default(),
        });
    }
    LeafCommand { name: name.to_string(), args }
}

/// 渲染单个参数的语法行占位符。
///
/// - 位置参数：`<value_name>`（value_name 缺失回退 arg id，统一小写）。
/// - 带值选项：`--long <value_name>`。
/// - 开关选项（`SetTrue`）：`--long`。
fn render_syntax_token(arg: &Arg) -> String {
    let value_name = arg_value_name(arg);
    match arg.get_long() {
        Some(long) => {
            if matches!(arg.get_action(), ArgAction::SetTrue) {
                format!("--{long}")
            } else {
                format!("--{long} <{value_name}>")
            }
        }
        None => format!("<{value_name}>"),
    }
}

/// 参数占位符：优先 `value_name`，缺失回退 arg id，统一小写（对齐手写 `<name>` 惯例）。
fn arg_value_name(arg: &Arg) -> String {
    let raw = arg
        .get_value_names()
        .and_then(|v| v.first())
        .map(|s| s.as_str().to_string())
        .unwrap_or_else(|| arg.get_id().as_str().to_string());
    raw.to_lowercase()
}

/// 渲染命令语法行（不含 `novel` 前缀由调用方拼接）。
fn render_syntax_line(cmd: &LeafCommand) -> String {
    let mut s = format!("novel {}", cmd.name);
    for arg in &cmd.args {
        if arg.required {
            s.push_str(&format!(" {}", arg.syntax_token));
        } else {
            s.push_str(&format!(" [{}]", arg.syntax_token));
        }
    }
    s
}

/// 渲染参数表。
fn render_param_table(cmd: &LeafCommand) -> String {
    let mut s = String::new();
    s.push_str("### 参数与选项\n\n");
    s.push_str("| 参数/选项 | 必填 | 说明 |\n");
    s.push_str("|---|---|---|\n");
    for arg in &cmd.args {
        let req = if arg.required { "是" } else { "否" };
        let display = markdown_escape(&arg.syntax_token);
        let help = markdown_escape(&arg.help);
        s.push_str(&format!("| `{display}` | {req} | {help} |\n"));
    }
    s
}

/// 渲染单命令生成段（标记 + 语法行代码块 + 参数表）。
fn render_commands_block(cmd: &LeafCommand) -> String {
    let mut s = String::new();
    s.push_str("<!-- @generated by spec-gen commands_source. DO NOT EDIT. -->\n");
    s.push_str("```\n");
    s.push_str(&render_syntax_line(cmd));
    s.push('\n');
    s.push_str("```\n\n");
    s.push_str(&render_param_table(cmd));
    s.push_str(GEN_END);
    s
}

/// 转义 markdown 表格单元格中的 `|`，避免破坏表格列结构。
fn markdown_escape(s: &str) -> String {
    s.replace('|', "\\|")
}

/// 从 `## \`novel ...\`` 标题行提取命令名（如 `setting set`）。
fn extract_command_name(line: &str) -> Option<String> {
    let line = line.trim_start();
    let inner = line.strip_prefix("## `novel ")?;
    inner.strip_suffix('`').map(|s| s.to_string())
}

/// 判断某行是否为一个命令段内「生成区」的结束边界（行为语义 / 退出码标题，或下一命令标题）。
///
/// 生成区（语法代码块 + 参数表）的结束由标题行界定；行为语义 / 退出码是手写段，须保留。
fn is_generated_region_end(line: &str) -> bool {
    let t = line.trim_start();
    if !t.starts_with('#') {
        return false;
    }
    // 下一命令标题（`## `）或行为语义/退出码标题（`### `/`#### ` 等任意层级）。
    t.starts_with("## ") || t.contains("行为语义") || t.contains("退出码")
}

/// 重新生成 commands.md 的生成段（语法行 + 参数表），保留手写段（描述、行为语义、退出码表）。
///
/// 对每个命令：把「语法代码块 + 参数表」（或已存在的生成段）替换为生成块，其余（描述、行为
/// 语义、退出码表）原样保留。多形态命令（如 `constraint render` / `constraint check` 双形态）
/// 只注入一个合并生成块，其余形态的语法/参数表删除但行为语义保留——clap 命令树本身只有一条
/// 命令，双形态是手写叙述。幂等：已有生成段时原位替换而非重复插入。
pub fn regenerate_commands_md(content: &str, commands: &[LeafCommand]) -> String {
    let blocks: HashMap<&str, String> = commands
        .iter()
        .map(|c| (c.name.as_str(), render_commands_block(c)))
        .collect();
    let lines: Vec<&str> = content.lines().collect();
    let mut out = String::new();
    let mut i = 0;
    while i < lines.len() {
        let line = lines[i];
        if let Some(name) = extract_command_name(line) {
            // 命令标题行：保留，进入命令体。
            out.push_str(line);
            out.push('\n');
            i += 1;
            let block = blocks.get(name.as_str());
            let mut generated = false;
            while i < lines.len() && extract_command_name(lines[i]).is_none() {
                let l = lines[i];
                // 只认本模块（commands_source）的生成段标记。其他生成段
                // （registry_source 行为语义/退出码段）标记宽匹配 GEN_MARKER_PREFIX
                // 会误删共存段（contract-registry-v2-04），故精确到模块名。
                let is_marker = l
                    .trim_start()
                    .starts_with("<!-- @generated by spec-gen commands_source");
                let is_fence = l.trim() == "```";
                if is_marker || is_fence {
                    // 生成区起始：首个注入生成块，后续形态/旧块只删除其语法/参数表。
                    if !generated {
                        generated = true;
                        if let Some(b) = block {
                            out.push_str(b);
                            out.push('\n');
                        }
                    }
                    i += 1;
                    if is_marker {
                        // 已有生成段：跳过到结束标记（含）。
                        while i < lines.len() && !lines[i].contains(GEN_END) {
                            i += 1;
                        }
                        if i < lines.len() {
                            i += 1;
                        }
                    } else {
                        // 首次生成：跳过到行为语义/退出码/下一命令标题。
                        while i < lines.len() && !is_generated_region_end(lines[i]) {
                            i += 1;
                        }
                    }
                    continue;
                }
                out.push_str(l);
                out.push('\n');
                i += 1;
            }
            continue;
        }
        out.push_str(line);
        out.push('\n');
        i += 1;
    }
    out
}

/// 应用生成到 commands.md。
pub fn apply_commands_md(path: &Path, commands: &[LeafCommand]) -> anyhow::Result<()> {
    let content = std::fs::read_to_string(path)?;
    let new_content = regenerate_commands_md(&content, commands);
    if new_content != content {
        std::fs::write(path, new_content)?;
    }
    Ok(())
}

/// 提取某命令的生成段（`<!-- @generated ... -->` 到 `<!-- /@generated -->`）。
fn extract_command_block(content: &str, name: &str) -> Option<String> {
    let heading = format!("## `novel {name}`");
    let hstart = content.find(&heading)?;
    let rest = &content[hstart..];
    let mstart = rest.find(GEN_MARKER_PREFIX)?;
    let after = &rest[mstart..];
    let mend = after.find(GEN_END)?;
    Some(after[..mend + GEN_END.len()].to_string())
}

/// 提取 commands.md 中全部 `## \`novel ...\`` 标题命令名（按出现序）。
fn extract_command_headings(content: &str) -> Vec<String> {
    content
        .lines()
        .filter_map(extract_command_name)
        .collect()
}

/// commands.md 漂移检查。返回漂移条目（命令名 / 缺生成段 / 命令数不一致）。
pub fn check_commands_drift(path: &Path, commands: &[LeafCommand]) -> Vec<String> {
    let on_disk = std::fs::read_to_string(path).unwrap_or_default();
    let mut drifts = Vec::new();

    // 命令数一致性：clap 命令树叶子数 vs 文档标题数。
    let headings = extract_command_headings(&on_disk);
    if headings.len() != commands.len() {
        drifts.push(format!(
            "commands.md 命令标题 {} 个，clap 命令树叶子 {} 个",
            headings.len(),
            commands.len()
        ));
    }

    for cmd in commands {
        let expected = render_commands_block(cmd);
        match extract_command_block(&on_disk, &cmd.name) {
            Some(actual) if actual == expected => {}
            Some(_) => drifts.push(format!("commands.md（{}）", cmd.name)),
            None => drifts.push(format!("commands.md（{} 缺生成段）", cmd.name)),
        }
    }
    drifts
}

/// 注册表交叉一致性校验（contract-registry-v2-03-command-contract-registry，design D3）。
///
/// 消费 `novel_cli::contracts::register_contracts()`（命令语义唯一结构化来源）与
/// `novel_cli::commands::build_cli()`（clap 语法唯一来源），复用 `validate_registry()` 的
/// 三项校验核心（叶子全覆盖 / 错误 ID 合法 / guard 可解析），另在此补充与生成链的关联匹配：
/// - clap 叶子命令路径集 ↔ 注册表 `command_path` 集一一对应（未登记 / 重复 / 组命令替代）。
/// - 注册表引用的错误 ID 均 ∈ ErrorCatalog（含目录反向追踪：公开 ID 被引用或显式豁免）。
/// 校验核心为单一函数（spec「校验核心单一实现」）；spec-gen 侧只做调用与汇总，不复制逻辑。
pub fn check_registry_consistency() -> Vec<String> {
    let mut issues = Vec::new();

    // 复用 novel-cli 内单一校验核心（validate_registry）。
    issues.extend(novel_cli::contracts::validate_registry());

    // 与 spec-gen 遍历的 clap 叶子集合做双向核对（与 validate_registry 内 clap 遍历同源，
    // 此处额外锁死「注册表路径 ⊆ spec-gen 叶子集合」的生成链关联，防两处遍历实现漂移）。
    let commands = collect_commands();
    let leaf_names: std::collections::HashSet<&str> =
        commands.iter().map(|c| c.name.as_str()).collect();
    let registry_paths: std::collections::HashSet<&str> =
        novel_cli::contracts::register_contracts()
            .iter()
            .map(|c| c.command_path)
            .collect();
    for p in &registry_paths {
        if !leaf_names.contains(p) {
            issues.push(format!(
                "注册表路径 {p} 不在 spec-gen clap 叶子集合中（生成链关联失配）"
            ));
        }
    }

    issues
}
